from random import randrange
prime = []

def sieve():
	N = 1000010
	pr = [True] * N
	pr[0] = pr[1] = False
	for i in range(int(N ** 0.5)):
		if pr[i]:
			for j in range(2 * i, N, i):
				pr[j] = False
	for i in range(N):
		if pr[i]:
			prime.append(i)

def miller_rabin(p):
	if p == 2 or p == 3:
		return True
	if p < 3 or p % 2 == 0:
		return False
	for i in range(1):
		rand = randrange(2, p - 2)
		n = p - 1
		while n % 2 == 0:
			n //= 2
		mod = pow(rand, n, p)
		if mod == 1 or mod == p - 1:
			continue
		flag = 0
		while n != p - 1:
			mod = pow(rand, n, p)
			if mod == p - 1:
				flag = 1
				break
			n *= 2
		if flag == 0:
			return 0
	return True

def fac(n):
	ans = 1
	for p in prime:
		if p * p * p > n:
			break
		count = 1
		while n % p == 0:
			n //= p
			count += 1
		ans = ans * count
	if miller_rabin(n):
		ans *= 2
	elif n ** 0.5 * n ** 0.5 == n and miller_rabin(int(n ** 0.5)):
		ans *= 3
	elif n != 1:
		ans *= 4
	return ans
